import {mkdtempSync,rmSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join} from 'node:path';
const {chromium}=await import(process.env.MEDIA_TEST_PLAYWRIGHT || 'playwright');
const base=new URL('../..',import.meta.url).pathname;
const vendor=process.env.MEDIA_DASHBOARD_VENDOR_DIR || new URL('../../../../../dashboard/dist/vendor',import.meta.url).pathname;
const result=await Bun.build({entrypoints:[`${base}/testdata/browser/entry.tsx`],outdir:'/tmp/media-browser-bundle',target:'browser',external:['react','react-dom/client','@apteva/ui-kit','react/jsx-runtime'],define:{'process.env.NODE_ENV':'"production"'}});
if(!result.success)throw new Error(result.logs.join('\n'));
const cssFiles=[...new Bun.Glob('*.css').scanSync(vendor+'/..')];
const cssLinks=cssFiles.map((_,i)=>`<link rel="stylesheet" href="/styles/${i}.css">`).join('');
const html=`<!doctype html><html><head>${cssLinks}<style>body{font:14px sans-serif}button{cursor:pointer}</style><script type="importmap">{"imports":{"react":"/vendor/react.mjs","react-dom/client":"/vendor/react-dom-client.mjs","react/jsx-runtime":"/vendor/react-jsx-runtime.mjs","@apteva/ui-kit":"/vendor/ui-kit.mjs"}}</script></head><body><div id="root"></div><script type="module" src="/entry.js"></script></body></html>`;
const fixtureDir=mkdtempSync(join(tmpdir(),'media-browser-'));
const videoPath=join(fixtureDir,'video.mp4');
const fixture=Bun.spawnSync(['ffmpeg','-hide_banner','-loglevel','error','-f','lavfi','-i','testsrc2=size=640x360:rate=24','-t','4','-c:v','libx264','-preset','ultrafast','-threads','2','-pix_fmt','yuv420p','-movflags','+faststart',videoPath]);
if(fixture.exitCode!==0)throw Error(fixture.stderr.toString());
const server=Bun.serve({port:0,fetch(req){const p=new URL(req.url).pathname;if(p==='/')return new Response(html,{headers:{'Content-Type':'text/html'}});if(p.startsWith('/styles/'))return new Response(Bun.file(vendor+'/../'+cssFiles[Number(p.split('/').pop()?.split('.')[0])]),{headers:{'Content-Type':'text/css'}});if(p==='/entry.js')return new Response(Bun.file('/tmp/media-browser-bundle/entry.js'));if(p.startsWith('/vendor/'))return new Response(Bun.file(vendor+'/'+p.split('/').pop()));return new Response('{}',{headers:{'Content-Type':'application/json'}})}});
const browser=await chromium.launch({headless:true,executablePath:process.env.MEDIA_TEST_CHROME,args:['--disable-dev-shm-usage']});
try{
 const page=await browser.newPage({viewport:{width:1280,height:900}});const errors:string[]=[];page.setDefaultTimeout(15000);page.on('pageerror',e=>{errors.push(String(e));console.error('PAGE ERROR',String(e))});
 const requests:string[]=[]; const posts:any[]=[];let description='before refresh';let transcript:any={found:false};
 const files=Array.from({length:150},(_,i)=>({file_id:String(i+1),project_id:'test-proj',name:`fixture-${i+1}.mp4`,folder:'/',has_video:true,has_audio:false,is_image:false,probe_status:'ok',width:1920,height:1080,duration_ms:4000,description:'before refresh',audience_rating:'general',derivations:[{id:i+1,kind:'thumbnail',status:'ok',storage_file_id:String(1000+i),width:320,height:180}]}));
 await page.route('**/api/**',async route=>{const url=new URL(route.request().url());requests.push(url.pathname+url.search);if(route.request().method()==='POST')posts.push({path:url.pathname+url.search,body:route.request().postDataJSON()});let data:any={};
  if(url.pathname.endsWith('/smartcrop'))data={crop:{crop_x:656,crop_y:0,crop_w:608,crop_h:1080},source_width:1920,source_height:1080};
  else if(url.pathname.endsWith('/renders')&&route.request().method()==='POST')data={render_id:7};
  else if(url.pathname.endsWith('/renders/7'))data={id:7,status:'ok',operation:'extract_reel',output_file_id:'99'};
  else if(url.pathname.endsWith('/content')){if(Number(url.pathname.split('/').at(-2))<1000){await route.fulfill({contentType:'video/mp4',body:Buffer.from(await Bun.file(videoPath).arrayBuffer())});return;}await route.fulfill({contentType:'image/svg+xml',body:'<svg xmlns="http://www.w3.org/2000/svg" width="320" height="180"><rect width="320" height="180" fill="#888"/></svg>'});return;}
  else if(url.pathname.endsWith('/transcript'))data=transcript;
  else if(url.pathname.endsWith('/media')){const offset=Number(url.searchParams.get('offset')||0);data={media:files.slice(offset,offset+100).map(f=>({...f,description}))}}
  else if(url.pathname.endsWith('/folders'))data={folders:[]};
  else if(url.pathname.endsWith('/facets'))data={counts:{all:150,video:150,audio:0,image:0}};
  else if(url.pathname.endsWith('/status'))data={ok:150};
  else if(url.pathname.includes('/media/')){const id=url.pathname.split('/').pop();data={media:{...files[Number(id)-1],description}}}
  await route.fulfill({json:data});
 });
 await page.goto(`http://localhost:${server.port}`);await page.waitForFunction(()=>typeof (window as any).mount==='function');
 await page.evaluate(()=> (window as any).mount('panel',{projectId:'test-proj',installId:42}));
 await page.getByText('fixture-100.mp4',{exact:true}).waitFor({state:'attached'});
 await page.getByRole('button',{name:/load more/i}).click();await page.getByText('fixture-150.mp4',{exact:true}).waitFor({state:'attached'});
 await page.getByText('fixture-150.mp4',{exact:true}).click();
 description='updated after event';await page.evaluate(()=> (window as any).emit({topic:'media.updated',data:{file_id:'150'}}));
 await page.waitForFunction(()=>document.body.textContent?.includes('updated after event'));
 if(await page.getByText('fixture-150.mp4',{exact:true}).count()<1)throw Error('pagination lost after event');
 if(requests.filter(u=>u.includes('/api/apps/media/')&&!u.includes('install_id=42')).length)throw Error('missing install routing');
 console.log('PASS panel pagination + selected refresh + install routing');
 await page.getByRole('button',{name:'9:16 reel',exact:true}).click();
 await page.locator('form video').evaluate(async(v:HTMLVideoElement)=>{v.muted=true;await v.play()});
 await page.waitForFunction(()=>Array.from(document.querySelectorAll('form video')).some((v:any)=>v.currentTime>0));
 console.log('PASS real video preview playback');
 await page.getByRole('button',{name:'Check smart crop',exact:true}).click();
 await page.getByText('Server smart-crop result on thumbnail fallback.',{exact:true}).waitFor();
 const quality=page.getByRole('combobox',{name:'Video quality'});
 if(await quality.inputValue()!=='legacy')throw Error('Legacy is not the default quality');
 if(await quality.locator('option').allTextContents().then(values=>values.join('|'))!=='Legacy (default)|Low — smaller files|Medium — balanced|High — more detail')throw Error('unexpected quality choices');
 await quality.selectOption('high');
 await page.screenshot({path:'/tmp/media-browser-render-dialog.png'});
 await page.getByRole('button',{name:'Start render',exact:true}).click();
 await page.locator('a[href*="/99/content"]').waitFor();
 const preview=posts.find(p=>p.path.includes('/smartcrop?'));const render=posts.find(p=>p.path.includes('/renders?'));
 if(!preview?.path.includes('install_id=42')||!render?.path.includes('install_id=42')||preview.body.end_ms!==render.body.params.end_ms||render.body.params.encoder_profile!=='high')throw Error('preview/render routing or parameters disagree: '+JSON.stringify(posts));
 console.log('PASS crop preview + render submission + matching range + High quality');
 await page.getByRole('button',{name:'9:16 reel',exact:true}).click();
 if(await page.getByRole('combobox',{name:'Video quality'}).inputValue()!=='legacy')throw Error('new render inherited nonlegacy quality');
 await page.locator('form').getByRole('button',{name:'Cancel',exact:true}).click();
 console.log('PASS Legacy default restored for each new render');
 await page.screenshot({path:'/tmp/media-browser-panel.png'});
 await page.evaluate(()=> (window as any).mount('transcript',{file_id:'1',projectId:'test-proj'}));await page.getByText('no transcript',{exact:true}).waitFor();
 transcript={found:true,transcript:{file_id:'1',status:'failed',error:'provider unavailable'}};
 await page.evaluate(()=> (window as any).emit({topic:'media.updated',data:{file_id:'1'}}));await page.getByText('provider unavailable',{exact:true}).waitFor();
 await page.evaluate(()=> (window as any).mount('transcript',{file_id:'2',projectId:'test-proj'}));transcript={found:true,transcript:{file_id:'2',status:'ok',text:'new file transcript'}};
 await page.evaluate(()=> (window as any).emit({topic:'media.transcribed',data:{file_id:'2'}}));await page.getByText('new file transcript',{exact:true}).waitFor();
 console.log('PASS transcript missing + failed + changed-file events');
 await page.screenshot({path:'/tmp/media-browser-verification.png',fullPage:true});
 if(errors.length)throw Error(errors.join('\n'));
 console.log('PASS no browser runtime errors');
}finally{await browser.close();server.stop();rmSync(fixtureDir,{recursive:true,force:true})}
